CREATE SCHEMA IF NOT EXISTS panel;
SET search_path=panel,pg_catalog;
CREATE TABLE IF NOT EXISTS pg_schema_migrations(version text PRIMARY KEY,sha256 text NOT NULL,applied_at timestamptz NOT NULL DEFAULT now());
CREATE OR REPLACE FUNCTION panel_now() RETURNS text LANGUAGE sql VOLATILE AS $$ SELECT to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD HH24:MI:SS') $$;
CREATE OR REPLACE FUNCTION json_valid(v text) RETURNS boolean LANGUAGE plpgsql IMMUTABLE AS $$ BEGIN PERFORM v::jsonb; RETURN true;EXCEPTION WHEN others THEN RETURN false;END $$;
CREATE OR REPLACE FUNCTION json_extract(v text,p text) RETURNS text LANGUAGE sql IMMUTABLE AS $$ SELECT v::jsonb #>> string_to_array(substr(p,3),'.') $$;
CREATE OR REPLACE FUNCTION panel_julianday(v text) RETURNS double precision LANGUAGE plpgsql STABLE AS $$ BEGIN RETURN extract(epoch FROM v::timestamptz)/86400.0+2440587.5;EXCEPTION WHEN others THEN RETURN NULL;END $$;
CREATE OR REPLACE FUNCTION panel_date(VARIADIC a text[]) RETURNS text LANGUAGE plpgsql STABLE AS $$ DECLARE t timestamptz;BEGIN t=a[1]::timestamptz;IF cardinality(a)>1 THEN t=t+a[2]::interval;END IF;RETURN to_char(t AT TIME ZONE 'UTC','YYYY-MM-DD');EXCEPTION WHEN others THEN RETURN NULL;END $$;
CREATE OR REPLACE FUNCTION panel_strftime(fmt text,v text,modifier text DEFAULT NULL) RETURNS text LANGUAGE plpgsql STABLE AS $$ DECLARE t timestamptz;BEGIN t=v::timestamptz;IF modifier IS NOT NULL THEN t=t+modifier::interval;END IF;IF fmt<>'%Y-%m' THEN RAISE EXCEPTION 'Formato no permitido';END IF;RETURN to_char(t AT TIME ZONE 'UTC','YYYY-MM');EXCEPTION WHEN others THEN RETURN NULL;END $$;
CREATE OR REPLACE FUNCTION immutable_audit() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='Auditoría inmutable';END $$;

CREATE TABLE IF NOT EXISTS admin (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY CHECK(id=1), username TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT panel_now());
CREATE TABLE IF NOT EXISTS sessions (token_hash TEXT PRIMARY KEY, expires_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS login_attempts (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, attempted_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS clients (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name TEXT NOT NULL, ruc TEXT UNIQUE, email TEXT, created_at TEXT NOT NULL DEFAULT panel_now());
CREATE TABLE IF NOT EXISTS licenses (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, client_id BIGINT NOT NULL REFERENCES clients(id) DEFERRABLE INITIALLY DEFERRED, reference TEXT NOT NULL UNIQUE, status TEXT NOT NULL DEFAULT 'BORRADOR', created_at TEXT NOT NULL DEFAULT panel_now());
CREATE TABLE IF NOT EXISTS authorized_devices (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, license_id BIGINT NOT NULL REFERENCES licenses(id) DEFERRABLE INITIALLY DEFERRED, installation_id TEXT NOT NULL UNIQUE, label TEXT, created_at TEXT NOT NULL DEFAULT panel_now());
CREATE TABLE IF NOT EXISTS activations (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, device_id BIGINT NOT NULL REFERENCES authorized_devices(id) DEFERRABLE INITIALLY DEFERRED, status TEXT NOT NULL DEFAULT 'PENDIENTE', created_at TEXT NOT NULL DEFAULT panel_now());
CREATE TABLE IF NOT EXISTS recovery_requests (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, device_id BIGINT NOT NULL REFERENCES authorized_devices(id) DEFERRABLE INITIALLY DEFERRED, status TEXT NOT NULL DEFAULT 'PENDIENTE', created_at TEXT NOT NULL DEFAULT panel_now());
CREATE TABLE IF NOT EXISTS history (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, event TEXT NOT NULL, detail TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT panel_now());
CREATE TABLE IF NOT EXISTS settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
INSERT INTO settings VALUES ('panel_name','Panel Central EDUXFAC') ON CONFLICT DO NOTHING;
